std_ticket_config_action.action_script:
(function(inputs, outputs) {
    // 'inputs' contains the values from the modal
    if (inputs) {
        if (inputs.u_short_description)
            current.short_description = inputs.u_short_description;
        if (inputs.new_date)
            current.fecha_licitacion = inputs.u_new_date;
        if (inputs.u_tipo_de_contrato)
            current.tipo_de_contrato = inputs.u_tipo_de_contrato;
        if (inputs.u_valor_estimado)
            current.valor_estimado = inputs.u_valor_estimado;
        current.update();
    }
})(inputs, outputs);

std_ticket_config_action.applicability_script:
(function() {
    if (current.getValue('state') == '1') {
        var user = gs.getUser();
        var targetGroup = "Responsables de información y registro [RIR]";
		var targetGroup2 = "Dirección General [DG] o Subdirección General [SG])";
        var targetGroup3 = "Secretaría General Técnica [SGT] o Gerente";
        if (gs.hasRole('admin') || (
			user.getCompanyID() == current.getValue('company') && 
				(user.isMemberOf(targetGroup) || user.isMemberOf(targetGroup2) || user.isMemberOf(targetGroup3))
			)
		)
            return true;
    }
    return false;
})();
